        $job=self::data()['jobs'][$jobid]??[];foreach(['last_apply'=>'Ostatni zapis','last_reconcile'=>'Zakończenie zapisu'] as $prefix=>$label){$stage=$job[$prefix.'_stage']??'';$code=$job[$prefix.'_error']??'';$stages=['before_native','native_content','native_elementor','native_thumbnail','batch_fields','native_readback','marker_job','marker_hash','state_commit','validate','receipt','complete'];if(is_string($stage)&&in_array($stage,$stages,true)&&is_string($code)&&(in_array($code,['php_type_error','php_error','unknown_apply_error'],true)||self::apply_error_code(new RuntimeException($code))===$code))echo '<p>'.esc_html($label).': '.esc_html($stage).' · '.esc_html($code).'.</p>';}
