        if($d['single_added_meta_key_matches'])echo '<p>Pełna migawka pasuje po wyłączeniu dokładnie jednego obecnego klucza: <code>'.esc_html(implode(', ',$d['single_added_meta_key_matches'])).'</code>. To dowód diagnostyczny, nie zgoda na pominięcie zabezpieczeń.</p>';else echo '<p>Nie potwierdzono pojedynczego dodanego klucza metadata. Sprawdzono '.(int)$d['meta_keys_checked'].' kluczy'.($d['meta_scan_limited']?' (limit 100)':'').'.</p>';echo '</details>';
